class GitHubRepositoryCloner:
    def __init__(
        self,
        clone_root: Path,
        allowed_root: Path,
        timeout_seconds: int,
        max_clone_bytes: int = 1_000_000_000,
        max_clone_files: int = 100_000,
        max_retained_clones: int = 10,
    ) -> None:
        self.clone_root = clone_root.resolve()
        self.allowed_root = allowed_root.resolve()
        self.timeout_seconds = timeout_seconds
        self.max_clone_bytes = max_clone_bytes
        self.max_clone_files = max_clone_files
        self.max_retained_clones = max_retained_clones

    def _validated_clone_root(self) -> Path:
        try:
            self.clone_root.relative_to(self.allowed_root)
        except ValueError as exc:
            raise RepositoryImportError(
                "ONBOARD_CLONE_ROOT must be inside ONBOARD_ALLOWED_ROOT"
            ) from exc
        self.clone_root.mkdir(parents=True, exist_ok=True)
        if not self.clone_root.is_dir():
            raise RepositoryImportError("The secure clone directory is unavailable")
        return self.clone_root

    @traced("repository.github_clone")
    def clone(self, repository_url: str) -> Path:
        repository = parse_github_repository(repository_url)
        clone_root = self._validated_clone_root()
        git = shutil.which("git")
        if git is None:
            raise GitUnavailableError(
                "Git is not installed or is not available on the server PATH"
            )
        destination = clone_root / (
            f"{repository.owner}--{repository.name}--{uuid.uuid4().hex[:10]}"
        )

class RepositoryQuestionService:
    def __init__(self, session: AnalysisSession) -> None:
        self.session = session
        self.report = session.report
        self.nodes = {node.id: node for node in self.report.nodes}

    def _read_lines(self, path: str) -> list[str]:
        if path not in self.session.source_paths:
            return []
        resolved = (self.session.root / Path(path)).resolve()
        try:
            resolved.relative_to(self.session.root)
        except ValueError:
            return []
        try:
            if resolved.stat().st_size > settings.max_python_file_bytes:
                return []
            return resolved.read_text(encoding="utf-8").splitlines()
        except (OSError, UnicodeError):
            return []

    def _readme_path(self) -> str | None:
        candidates = [
            path
            for path in self.session.source_paths
            if Path(path).name.lower() in {"readme.md", "readme.mdx", "readme.txt"}
        ]
        return min(
            candidates,
            key=lambda path: (len(Path(path).parts), len(path), path.lower()),
            default=None,
        )

    def _is_overview_question(self, question: str) -> bool:
        normalized = question.lower()
        if normalized.lstrip().startswith(("where ", "how is ", "how does ")):
            return False
        return any(phrase in normalized for phrase in _OVERVIEW_PHRASES)

    def _section(
        self, lines: list[str], heading_pattern: str
    ) -> tuple[int, int] | None:
        pattern = re.compile(heading_pattern, re.IGNORECASE)

def repository_identity(root: Path) -> str | None:
    marker = root / ".waypoint-managed"
    if marker.is_file():
        try:
            identity = _repository_from_url(marker.read_text(encoding="utf-8"))
            if identity:
                return identity
        except (OSError, UnicodeError):
            pass
    config_path = root / ".git" / "config"
    if not config_path.is_file():
        return None
    parser = configparser.ConfigParser()
    try:
        parser.read(config_path, encoding="utf-8")
    except (OSError, configparser.Error):
        return None
    preferred = ['remote "origin"']
    sections = preferred + [section for section in parser.sections() if section.startswith("remote ")]
    for section in dict.fromkeys(sections):
        if parser.has_option(section, "url"):
            identity = _repository_from_url(parser.get(section, "url"))
            if identity:
                return identity
    return None

